// Mise en LOTS de 40 items : le nœud HTTP s'exécute une fois par item
// entrant — un item = un lot, c'est le mécanisme voulu.
const items = $input.all().map(x => x.json);
if (!items.length) throw new Error('Aucun item pertinent sans lecture événementielle — rien à traiter.');
const lots = [];
for (let i = 0; i < items.length; i += 40) lots.push(items.slice(i, i + 40));
const consigne = `Tu lis des titres d'articles de presse professionnelle. Pour CHAQUE item, dis s'il rapporte un ÉVÉNEMENT concret (quelque chose qui s'est produit : décision, transaction, ouverture, fermeture, règlement) — par opposition à un contenu éditorial (guide d'achat, présentation de produit ancien, histoire, opinion).

Réponds STRICTEMENT en JSON, sans texte autour :
{"lectures":[{"item_id":123,"est_evenement":true,"type":"investissement","acteur":"Nom","zone":"pays ou région","sens_sous_traitance":"opportunite","resume":"une phrase factuelle"}, {"item_id":124,"est_evenement":false}]}

Règles impératives :
- type parmi : investissement, fermeture_reduction, rachat_fusion, reglementation, lancement_produit, resultat_financier, partenariat, autre.
- sens_sous_traitance parmi : opportunite, menace, neutre — du point de vue d'un sous-traitant mécanique de précision.
- UNIQUEMENT les item_id fournis. Un item douteux est est_evenement:false — ne force jamais.
- Le resume ne contient AUCUN chiffre qui ne soit pas dans le titre. Style : phrases simples, sans tiret cadratin (—), ponctuation ordinaire.`;
return lots.map(l => ({ json: {
  consigne,
  charge: l.map(x => `${x.item_id} | [${x.sector_code}] ${x.titre}`).join('\n'),
  item_ids: l.map(x => x.item_id),
  secteurs: Object.fromEntries(l.map(x => [x.item_id, x.sector_code]))
} }));

// CONTRÔLES DÉTERMINISTES sur la sortie du modèle — le rang 1 avant tout :
//  - JSON valide, item_id appartenant AU LOT (une lecture inventée est jetée
//    et comptée), vocabulaire fermé respecté ;
//  - la règle « aucun chiffre absent du titre » est portée par la CONSIGNE
//    au modèle ; AUCUN contrôle déterministe ne la vérifie ici (constaté le
//    01.09.2026 : le commentaire antérieur affirmait un signalement qui
//    n'était pas implémenté). Perspective : extraction des nombres et
//    compteur d'incident au bilan.
function texte(x) {
  if (Array.isArray(x.candidates)) return ((x.candidates[0] || {}).content?.parts || []).filter(p => p.text).map(p => p.text).join('');
  if (Array.isArray(x.content)) return x.content.filter(b => b.type === 'text').map(b => b.text).join('');
  return '';
}
const TYPES = ['investissement','fermeture_reduction','rachat_fusion','reglementation','lancement_produit','resultat_financier','partenariat','autre'];
const SENS = ['opportunite','menace','neutre'];
const run_id = $('Ouvrir le run').first().json.run_id;
const sorties = []; let jetes = 0, non_evenements = 0, lots_illisibles = 0;
// Admission GLOBALE : l'appariement lot->réponse par index est fragile
// (constaté au premier run : 757 lectures jetées pour rien) ; les item_id
// étant uniques dans tout le corpus, un ensemble global contrôle aussi
// bien les inventions, sans dépendre de l'ordre des réponses.
const admis = new Map();
for (const lot of $('Mettre en lots').all())
  for (const id of lot.json.item_ids) admis.set(Number(id), lot.json.secteurs[String(id)] ?? null);
$input.all().forEach((item) => {
  let d;
  try { d = JSON.parse(String(texte(item.json)).replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim()); }
  catch (e) { lots_illisibles++; return; }
  for (const l of (d.lectures || [])) {
    const id = Number(l.item_id);
    if (!admis.has(id)) { jetes++; continue; }
    if (!l.est_evenement) { non_evenements++; continue; }
    if (!TYPES.includes(l.type) || !SENS.includes(l.sens_sous_traitance)) { jetes++; continue; }
    sorties.push({ json: {
      item_id: id, run_id,
      sector_code: admis.get(id),
      type_evenement: l.type, acteur: l.acteur ?? null, zone: l.zone ?? null,
      sens_sous_traitance: l.sens_sous_traitance,
      resume: String(l.resume || '').replace(/\s+—\s+/g, ' : ').slice(0, 500),
      modele: $env.MODELE_GOOGLE
    } });
  }
});
if (!sorties.length) throw new Error(`Aucun événement retenu (${non_evenements} non-événements, ${jetes} lectures jetées, ${lots_illisibles} lots illisibles).`);
sorties[0].json._bilan = { evenements: sorties.length, non_evenements, jetes, lots_illisibles };
return sorties;

